<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE)session_start();$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');if(empty($_SESSION['user'])){header('Location:index.php');exit;}
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);require_once $root.'/app/Core/UnifiedSidebar.php';require_once $root.'/app/Core/ProjectFollowup.php';ensureProjectFollowupSchema($db);$projectId=(int)($_GET['project_id']??0);$period=(string)($_GET['period']??'open');$today=date('Y-m-d');$where=['p.next_followup_date IS NOT NULL','p.followup_closed_at IS NULL'];$params=[];if($projectId){$where[]='p.id=?';$params[]=$projectId;}if($period==='due')$where[]='p.next_followup_date<=CURDATE()';elseif($period==='week')$where[]='p.next_followup_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 7 DAY)';if(($_SESSION['user']['role']??'')!=='admin'){$where[]='p.followup_responsible_user_id=?';$params[]=(int)$_SESSION['user']['id'];}
$sql="SELECT p.id project_id,p.next_followup_date,u.name responsible_name,p.project_number,p.name project_name,c.business_name,(SELECT COUNT(*) FROM quotes q WHERE q.project_id=p.id) quote_count FROM projects p JOIN clients c ON c.id=p.client_id LEFT JOIN users u ON u.id=p.followup_responsible_user_id WHERE ".implode(' AND ',$where).' ORDER BY p.next_followup_date,p.id';$stmt=$db->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$e=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agenda de seguimiento · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}.main{margin-left:var(--sidebar);padding:32px 4%}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:8px;padding:9px 13px;background:var(--o);color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.btn.light{background:#edf0f3;color:var(--ink)}.btn.active{background:#252b32;color:#fff}.muted{color:var(--muted)}.pill{display:inline-block;padding:5px 9px;border-radius:20px;background:#edf0f3;font-size:12px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid var(--line)}th{font-size:12px;text-transform:uppercase;color:var(--muted)}.scroll{overflow:auto}@media(max-width:900px){.main{margin-left:0;padding:22px 18px}}</style></head><body><?php erpSidebar('quotes');?><main class="main"><div class="actions"><div style="flex:1"><span class="muted">Agenda comercial</span><h1>Seguimiento de clientes</h1><p class="muted">Un único contacto programado por proyecto, aunque tenga varios presupuestos.</p></div><?php if($projectId):?><a class="btn light" href="?a=project&id=<?=$projectId?>">Volver al proyecto</a><?php endif;?></div><div class="card"><div class="actions"><a class="btn <?=$period==='open'?'active':'light'?>" href="?a=followup_agenda<?=$projectId?'&project_id='.$projectId:''?>">Todos</a><a class="btn <?=$period==='due'?'active':'light'?>" href="?a=followup_agenda&period=due<?=$projectId?'&project_id='.$projectId:''?>">Vencidos y hoy</a><a class="btn <?=$period==='week'?'active':'light'?>" href="?a=followup_agenda&period=week<?=$projectId?'&project_id='.$projectId:''?>">Próximos 7 días</a></div></div><div class="card scroll"><table><tr><th>Fecha</th><th>Cliente</th><th>Proyecto</th><th>Presupuestos</th><th>Responsable</th><th>Situación</th><th></th></tr><?php foreach($rows as $row):$delta=(int)floor((strtotime($today)-strtotime($row['next_followup_date']))/86400);$due=$delta>=0;?><tr style="<?=$due?'background:#fff7f2':''?>"><td><b><?=date('d/m/Y',strtotime($row['next_followup_date']))?></b></td><td><?=$e($row['business_name'])?></td><td><a href="?a=project&id=<?=(int)$row['project_id']?>"><?=$e($row['project_number'].' · '.$row['project_name'])?></a></td><td><?=$e($row['quote_count'].' presupuesto'.((int)$row['quote_count']===1?'':'s'))?></td><td><?=$e($row['responsible_name']?:'Sin asignar')?></td><td><span class="pill" style="<?=$due?'background:#ffe5e5;color:#a92727':''?>"><?=$delta>0?'Vencido '.$delta.' día'.($delta===1?'':'s'):($delta===0?'Contactar hoy':'En '.abs($delta).' día'.(abs($delta)===1?'':'s'))?></span></td><td><a class="btn light" href="?a=project_followup&id=<?=(int)$row['project_id']?>">Gestionar</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="muted">No hay contactos para este filtro.</td></tr><?php endif;?></table></div></main></body></html>
